// Generated by Corral. Renders one Symfony VarDumper server payload
// (base64(serialize([Data, context]))) read from stdin into JSON on stdout.
//
// Safety: the payload is first unserialized with NO classes allowed to read
// the source path; then only VarDumper's own Cloner/Caster classes are
// allowed, which rules out object-injection gadgets from the app's vendor.
error_reporting(E_ALL & ~E_DEPRECATED);
$raw = base64_decode(trim((string) stream_get_contents(STDIN)), true);
if ($raw === false) {
    fwrite(STDERR, "invalid base64\n");
    exit(2);
}

$peek = @unserialize($raw, ['allowed_classes' => false]);
$context = is_array($peek) && isset($peek[1]) && is_array($peek[1]) ? $peek[1] : [];
$file = $context['source']['file'] ?? null;

// Find the project's Composer autoloader by walking up from the dump's file.
$autoload = null;
for ($dir = is_string($file) ? dirname($file) : null; $dir && $dir !== '/' && $dir !== '.'; $dir = dirname($dir)) {
    if (is_file($dir . '/vendor/autoload.php') && is_dir($dir . '/vendor/symfony/var-dumper')) {
        $autoload = $dir . '/vendor/autoload.php';
        break;
    }
}
if ($autoload === null) {
    fwrite(STDERR, "cannot locate symfony/var-dumper for $file\n");
    exit(3);
}
require $autoload;

$vd = dirname($autoload) . '/symfony/var-dumper';
$allowed = [];
foreach (['Cloner' => 'Symfony\\Component\\VarDumper\\Cloner\\', 'Caster' => 'Symfony\\Component\\VarDumper\\Caster\\'] as $sub => $ns) {
    foreach (glob("$vd/$sub/*.php") ?: [] as $f) {
        $allowed[] = $ns . basename($f, '.php');
    }
}
$payload = @unserialize($raw, ['allowed_classes' => $allowed]);
if (!is_array($payload) || !($payload[0] ?? null) instanceof \Symfony\Component\VarDumper\Cloner\Data) {
    fwrite(STDERR, "unexpected payload\n");
    exit(4);
}
[$data, $context] = $payload;

$html = (new \Symfony\Component\VarDumper\Dumper\HtmlDumper())->dump($data, true);
$cli = new \Symfony\Component\VarDumper\Dumper\CliDumper();
$cli->setColors(false);
$text = $cli->dump($data, true);

echo json_encode([
    'time' => (float) ($context['timestamp'] ?? microtime(true)),
    'label' => $context['label'] ?? null,
    'html' => $html,
    'text' => $text,
    'file' => $context['source']['file'] ?? null,
    'line' => isset($context['source']['line']) ? (int) $context['source']['line'] : null,
    'sapi' => isset($context['cli']) ? 'cli' : 'fpm-fcgi',
    'host' => null,
    'method' => $context['request']['method'] ?? null,
    'uri' => $context['request']['uri'] ?? ($context['cli']['command_line'] ?? null),
